// EF Core 9 breaking change: Migrate() can no longer run inside a
// user-started transaction — it now manages its own transaction per
// migration.  The execution-strategy wrapper is still valid.
void ApplyMigrations(AppDbContext db)
{
    var strategy = db.Database.CreateExecutionStrategy();
    strategy.Execute(() =>
    {
        db.Database.Migrate();
    });
}

